"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["25151"],{873781(t){t.exports=JSON.parse('{"id":12475,"title":"\u0639\u0645\u0644 \u0627\u062E\u062A\u0628\u0627\u0631 \u0623\u0633\u0626\u0644\u0629 \u0645\u0646 \u0645\u062A\u0639\u062F\u062F \u0634\u0627\u0645\u0644 \u0645\u0646 \u0645\u0642\u0631\u0631 \u0642\u0627\u0646\u0648\u0646\u064A","description":"\u0627\u0644\u0645\u0648\u0636\u0648\u0639: \u0625\u0646\u0634\u0627\u0621 \u0628\u0646\u0643 \u0623\u0633\u0626\u0644\u0629 \u0634\u0627\u0645\u0644 \u0628\u0646\u0638\u0627\u0645 (MCQ) \u0644\u0640 (\u0627\u0633\u0645 \u0627\u0644\u0645\u0642\u0631\u0631 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A \u0647\u0646\u0627)\\n\u0627\u0644\u0647\u062F\u0641: \u0628\u0635\u0641\u062A\u0643 \u062E\u0628\u064A\u0631\u0627\u064B \u0642\u0627\u0646\u0648\u0646\u064A\u0627\u064B \u0648\u0623\u0633\u062A\u0627\u0630\u0627\u064B \u062C\u0627\u0645\u0639\u064A\u0627\u064B\u060C \u0645\u0637\u0644\u0648\u0628 \u0645\u0646\u0643 \u0628\u0646\u0627\u0621 \u0627\u062E\u062A\u0628\u0627\u0631 \\"\u0634\u0627\u0645\u0644 \u0648\u0645\u0627\u0646\u0639\\" \u064A\u063A\u0637\u064A \u0643\u0627\u0641\u0629 \u0646\u0635\u0648\u0635 \u0627\u0644\u0645\u0648\u0627\u062F \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0641\u064A \u0647\u0630\u0627 \u0627\u0644\u0645\u0642\u0631\u0631\u060C \u0648\u0641\u0642 \u0627\u0644\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u062A\u0627\u0644\u064A\u0629:\\n\u0623\u0648\u0644\u0627\u064B: \u0627\u0644\u0647\u064A\u0643\u0644 \u0627\u0644\u0641\u0646\u064A \u0644\u0644\u0633\u0624\u0627\u0644 (\u0625\u0644\u0632\u0627\u0645\u064A): \u064A\u062C\u0628 \u0623\u0646 \u064A\u0638\u0647\u0631 \u0643\u0644 \u0633\u0624\u0627\u0644 \u0628\u0647\u0630\u0627 \u0627\u0644\u062A\u0646\u0633\u064A\u0642 \u062D\u0635\u0631\u0627\u064B:\\n\u2022\\t\u0627\u0644\u0633\u0624\u0627\u0644: (\u0646\u0635 \u0627\u0644\u0633\u0624\u0627\u0644)\\n\u2022\\t\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631 \u0623: (\u0646\u0635)\\n\u2022\\t\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631 \u0628: (\u0646\u0635)\\n\u2022\\t\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631 \u062C: (\u0646\u0635)\\n\u2022\\t\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631 \u062F: (\u0646\u0635)\\n\u2022\\t\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631 \u0627\u0644\u0635\u062D\u064A\u062D: (\u0645\u062B\u0644\u0627\u064B: \u0628)\\n\u2022\\t\u0627\u0644\u0633\u0646\u062F \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A: (\u0631\u0642\u0645 \u0627\u0644\u0645\u0627\u062F\u0629 + \u0646\u0635\u0647\u0627 \u0623\u0648 \u0641\u062D\u0648\u0627\u0647\u0627 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A)\\n\u062B\u0627\u0646\u064A\u0627\u064B: \u0627\u0644\u0645\u062A\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u0646\u0648\u0639\u064A\u0629 \u0648\u0627\u0644\u0643\u0645\u064A\u0629:\\n1.\\t\u0627\u0644\u0634\u0645\u0648\u0644\u064A\u0629: \u064A\u062C\u0628 \u062A\u063A\u0637\u064A\u0629 \u0643\u0644 \u0645\u0627\u062F\u0629 \u0645\u0646 \u0645\u0648\u0627\u062F \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0628\u0623\u0633\u0626\u0644\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0648\u063A\u064A\u0631 \u0645\u0628\u0627\u0634\u0631\u0629. \u0644\u0627 \u064A\u064F\u0633\u0645\u062D \u0628\u062A\u062C\u0627\u0648\u0632 \u0623\u064A \u0645\u0627\u062F\u0629.\\n2.\\t\u0627\u0644\u062A\u062F\u0631\u062C: \u0648\u0632\u0639 \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0628\u064A\u0646 (30% \u0645\u0633\u062A\u0648\u0649 \u0633\u0647\u0644/\u0645\u0628\u0627\u0634\u0631\u060C 40% \u0645\u0633\u062A\u0648\u0649 \u0645\u062A\u0648\u0633\u0637/\u062A\u062D\u0644\u064A\u0644\u064A\u060C 30% \u0645\u0633\u062A\u0648\u0649 \u0635\u0639\u0628/\u0642\u0636\u0627\u064A\u0627 \u0648\u0627\u0633\u062A\u0646\u0628\u0627\u0637).\\n3.\\t\u0627\u0644\u0639\u0634\u0648\u0627\u0626\u064A\u0629: \u062A\u0623\u0643\u062F \u0645\u0646 \u062A\u0648\u0632\u064A\u0639 \u0627\u0644\u0625\u062C\u0627\u0628\u0627\u062A \u0627\u0644\u0635\u062D\u064A\u062D\u0629 \u0628\u0634\u0643\u0644 \u0639\u0634\u0648\u0627\u0626\u064A \u062A\u0645\u0627\u0645\u0627\u064B \u0628\u064A\u0646 (\u0623\u060C \u0628\u060C \u062C\u060C \u062F) \u0644\u0636\u0645\u0627\u0646 \u0639\u062F\u0645 \u0648\u062C\u0648\u062F \u0646\u0645\u0637 \u0645\u062A\u0643\u0631\u0631.\u0648\u0628\u062D\u064A\u062B \u0645\u0641\u064A\u0634 \u062D\u0631\u0641 \u0627\u062E\u062A\u064A\u0627\u0631 \u0635\u062D\u064A\u062D \u0645\u062A\u0643\u0631\u0631 \u0623\u0643\u062A\u0631 \u0645\u0646 \u0645\u0631\u062A\u064A\u0646 \u0648\u0631\u0627 \u0628\u0639\u0636\\n4.\\t\u0627\u0644\u0643\u0645: \u0627\u0644\u0639\u062F\u062F \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0644\u0627 \u064A\u0642\u0644 \u0639\u0646 200) \u0633\u0624\u0627\u0644. (\u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0627\u0644\u0645\u0627\u062F\u0629 \u0627\u0644\u0639\u0644\u0645\u064A\u0629 \u0636\u062E\u0645\u0629\u060C \u0627\u0633\u062A\u0645\u0631 \u0641\u064A \u062A\u0648\u0644\u064A\u062F \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u062D\u062A\u0649 \u062A\u063A\u0637\u064A \u0643\u0627\u0641\u0629 \u0627\u0644\u062A\u0641\u0627\u0635\u064A\u0644.\\n\u062B\u0627\u0644\u062B\u0627\u064B: \u0622\u0644\u064A\u0629 \u0627\u0644\u062A\u0646\u0641\u064A\u0630:\\n\u2022\\t\u0627\u0628\u062F\u0623 \u0627\u0644\u0622\u0646 \u0628\u062A\u0648\u0644\u064A\u062F \u0623\u0648\u0644 (\u0645\u062B\u0644\u0627\u064B: 30 \u0633\u0624\u0627\u0644\u0627\u064B) \u0645\u0646 \u0627\u0644\u062F\u0641\u0639\u0629 \u0627\u0644\u0623\u0648\u0644\u0649.\\n\u2022\\t\u0627\u0646\u062A\u0638\u0631 \u0645\u0646\u064A \u0643\u0644\u0645\u0629 \\"\u0627\u0633\u062A\u0645\u0631\\" \u0644\u062A\u0648\u0644\u064A\u062F \u0627\u0644\u062F\u0641\u0639\u0629 \u0627\u0644\u062A\u064A \u062A\u0644\u064A\u0647\u0627\u060C \u0648\u0647\u0643\u0630\u0627 \u062D\u062A\u0649 \u0646\u0635\u0644 \u0644\u0644\u0639\u062F\u062F \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0644\u0636\u0645\u0627\u0646 \u062C\u0648\u062F\u0629 \u0627\u0644\u0645\u062E\u0631\u062C\u0627\u062A \u0648\u0639\u062F\u0645 \u0627\u0646\u0642\u0637\u0627\u0639 \u0627\u0644\u0646\u0635.\\n","remark":"\u0639\u0645\u0644 \u0627\u062E\u062A\u0628\u0627\u0631 \u0623\u0633\u0626\u0644\u0629 \u0645\u0646 \u0645\u062A\u0639\u062F\u062F \u0634\u0627\u0645\u0644 \u0645\u0646 \u0645\u0642\u0631\u0631 \u0642\u0627\u0646\u0648\u0646\u064A","owner":"mixdream3030","upvotes":0,"downvotes":0,"updatedAt":"2026-05-01T12:54:47.897Z"}')}}]);